<!-- Inline JavaScript for Reactive Filtering & Micro-interactions -->
<script>
  (function() {
    let currentCategory = 'all';
    let currentSkinType = 'all';
    let currentConcern = 'all';

    const catButtons = document.querySelectorAll('.cat-pill');
    const skinTypeSelect = document.getElementById('skin-type-select');
    const concernSelect = document.getElementById('concern-select');
    const productGrid = document.getElementById('product-grid');
    const productCards = document.querySelectorAll('.product-item');
    const productCountEl = document.getElementById('product-count');
    const noResultsEl = document.getElementById('no-results');
    const resetFilterBtn = document.getElementById('reset-filter-btn');

    function applyFilters() {
      let visibleCount = 0;

      productCards.forEach(card => {
        const cat = card.getAttribute('data-cat');
        const type = card.getAttribute('data-type');
        const concern = card.getAttribute('data-concern');

        const matchCat = (currentCategory === 'all' || cat === currentCategory);
        const matchType = (currentSkinType === 'all' || type === currentSkinType || type === 'all');
        const matchConcern = (currentConcern === 'all' || concern === currentConcern);

        if (matchCat && matchType && matchConcern) {
          card.classList.remove('hidden');
          visibleCount++;
        } else {
          card.classList.add('hidden');
        }
      });

      if (productCountEl) {
        productCountEl.textContent = `Menampilkan ${visibleCount} formula terpilih`;
      }

      if (visibleCount === 0) {
        productGrid.classList.add('hidden');
        noResultsEl.classList.remove('hidden');
        noResultsEl.classList.add('flex');
      } else {
        productGrid.classList.remove('hidden');
        noResultsEl.classList.add('hidden');
        noResultsEl.classList.remove('flex');
      }
    }

    // Category Tabs Logic
    catButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        catButtons.forEach(b => {
          b.classList.remove('bg-primary', 'text-on-primary');
          b.classList.add('bg-surface-container-low', 'text-on-surface-variant');
        });
        btn.classList.add('bg-primary', 'text-on-primary');
        btn.classList.remove('bg-surface-container-low', 'text-on-surface-variant');
        currentCategory = btn.getAttribute('data-category');
        applyFilters();
      });
    });

    // Sub filter selects
    if (skinTypeSelect) {
      skinTypeSelect.addEventListener('change', (e) => {
        currentSkinType = e.target.value;
        applyFilters();
      });
    }

    if (concernSelect) {
      concernSelect.addEventListener('change', (e) => {
        currentConcern = e.target.value;
        applyFilters();
      });
    }

    // Reset Filter Button
    if (resetFilterBtn) {
      resetFilterBtn.addEventListener('click', () => {
        currentCategory = 'all';
        currentSkinType = 'all';
        currentConcern = 'all';

        catButtons.forEach(b => {
          if (b.getAttribute('data-category') === 'all') {
            b.classList.add('bg-primary', 'text-on-primary');
            b.classList.remove('bg-surface-container-low', 'text-on-surface-variant');
          } else {
            b.classList.remove('bg-primary', 'text-on-primary');
            b.classList.add('bg-surface-container-low', 'text-on-surface-variant');
          }
        });

        if (skinTypeSelect) skinTypeSelect.value = 'all';
        if (concernSelect) concernSelect.value = 'all';

        applyFilters();
      });
    }

    // Add to cart discrete visual feedback
    const addButtons = document.querySelectorAll('.add-to-cart');
    addButtons.forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const icon = btn.querySelector('.material-symbols-outlined');
        if (icon) {
          const original = icon.textContent;
          icon.textContent = 'check';
          btn.classList.add('bg-secondary', 'text-on-secondary');
          setTimeout(() => {
            icon.textContent = original;
            btn.classList.remove('bg-secondary', 'text-on-secondary');
          }, 1400);
        }
      });
    });
  })();
</script></main><footer class="w-full bg-surface-container-lowest"><div class="max-w-[1440px] mx-auto px-margin-mobile md:px-margin-tablet lg:px-margin pt-space-xl pb-space-lg"><div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-12 gap-space-lg mb-space-xl"><div class="lg:col-span-4 flex flex-col justify-between"><div class="space-y-space-sm"><div class="flex items-center gap-space-xs"><span class="font-headline-sm text-headline-sm tracking-tight text-primary font-light">GlowAura</span><span class="w-1.5 h-1.5 rounded-full bg-secondary-container"></span></div><p class="font-body-sm text-body-sm text-on-surface-variant max-w-sm font-light leading-relaxed">Kurasi mindful skincare yang merayakan kejernihan, sains dermatologi, dan ketenangan ritual perawatan diri harian.</p></div><div class="mt-space-md pt-space-md"><div class="inline-flex items-center gap-space-xs px-space-md py-space-xs rounded-full bg-surface-container-low text-on-surface-variant"><span class="material-symbols-outlined text-[16px] text-secondary">verified</span><span class="font-label-sm text-label-sm tracking-wider uppercase">100% BPOM Verified &amp; Dermatologist Tested</span></div></div></div><div class="lg:col-span-2 space-y-space-sm"><div class="font-title-md text-title-md text-primary font-medium">Koleksi</div><ul class="space-y-space-xs"><li class="font-body-sm text-body-sm text-on-surface-variant hover:text-secondary transition-colors duration-200"><a data-path="katalog" href="#">Semua Formula</a></li><li class="font-body-sm text-body-sm text-on-surface-variant hover:text-secondary transition-colors duration-200"><a data-path="katalog" href="#">Serum Konsentrat</a></li><li class="font-body-sm text-body-sm text-on-surface-variant hover:text-secondary transition-colors duration-200"><a data-path="katalog" href="#">Barrier Repair</a></li><li class="font-body-sm text-body-sm text-on-surface-variant hover:text-secondary transition-colors duration-200"><a data-path="katalog" href="#">Sunscreen